30	func (uc *AuthUseCase) Register(ctx context.Context, req domain.RegisterRequest) (*domain.AuthResponse, error) {
31		existing, _ := uc.userRepo.FindByEmail(ctx, req.Email)
32		if existing != nil {
33			return nil, ErrEmailAlreadyExists
34		}
35	
36		hashedPassword, err := hash.HashPassword(req.Password)
37		if err != nil {
38			return nil, err
39		}
40	
41		now := time.Now()
42		user := &domain.User{
43			ID:              uuid.New(),
44			Email:           req.Email,
45			PasswordHash:    hashedPassword,
46			DisplayName:     req.DisplayName,
47			Role:            domain.RoleStudent,
48			IsEmailVerified: false,
49			StreakDays:      0,
50			TotalXP:         0,
51			CreatedAt:       now,
52			UpdatedAt:       now,
53		}
54	
55		if err := uc.userRepo.Create(ctx, user); err != nil {
56			return nil, err
57		}
58	
59		accessToken, err := uc.jwtManager.GenerateAccessToken(user.ID, user.Email, string(user.Role))
60		if err != nil {
61			return nil, err
62		}
63	
64		refreshToken, err := uc.jwtManager.GenerateRefreshToken(user.ID)
65		if err != nil {
66			return nil, err
67		}
68	
69		return &domain.AuthResponse{
70			User:         *user,
71			AccessToken:  accessToken,
72			RefreshToken: refreshToken,
73			ExpiresIn:    900,
74		}, nil
75	}
