47		questions, err := uc.examRepo.ListQuestions(ctx, examID)
48		if err != nil {
49			return nil, err
50		}
51	
52		// Strip correct answers from options — client must never receive is_correct
53		for i := range questions {
54			for j := range questions[i].Options {
55				questions[i].Options[j].IsCorrect = false
56			}
57		
58		}
