63	func (uc *ExamUseCase) StartAttempt(ctx context.Context, userID uuid.UUID, req domain.StartAttemptRequest) (*domain.Attempt, error) {
64		exam, err := uc.examRepo.FindExamByID(ctx, req.ExamID)
65		if err != nil {
66			return nil, ErrExamNotFound
67		}
68	
69		// Get all question IDs from the bank
70		allIDs, err := uc.examRepo.ListQuestionIDs(ctx, req.ExamID)
71		if err != nil {
72			return nil, err
73		}
74		if len(allIDs) == 0 {
75			return nil, errors.New("no questions available for this exam")
76		}
77	
78		// Determine how many questions to take for this attempt
79		// Exam mode: use exam's total_questions (realistic count, e.g. 60 for JNCIA)
80		// Practice mode: use exam's total_questions too, but allow user to specify custom count
81		targetCount := exam.TotalQuestions
82		if req.QuestionCount > 0 && req.QuestionCount < targetCount {
83			targetCount = req.QuestionCount
84		}
85		if targetCount > len(allIDs) {
86			targetCount = len(allIDs)
87		}
88	
89		// Randomly select targetCount questions from the bank
90		rng := rand.New(rand.NewSource(time.Now().UnixNano()))
91		selected := make([]uuid.UUID, len(allIDs))
92		copy(selected, allIDs)
93		rng.Shuffle(len(selected), func(i, j int) {
94			selected[i], selected[j] = selected[j], selected[i]
95		})
96		selected = selected[:targetCount]
97	
98		now := time.Now()
99		attempt := &domain.Attempt{
100			ID:                uuid.New(),
101			UserID:            userID,
102			ExamID:            req.ExamID,
103			Status:            domain.AttemptStatusInProgress,
104			Mode:              req.Mode,
105			StartedAt:         now,
106			DurationSeconds:   exam.DurationMinutes * 60,
107			QuestionsTotal:    targetCount,
108			QuestionsAnswered: 0,
109			QuestionsCorrect:  0,
110			CreatedAt:         now,
111		}
112	
113		if err := uc.attemptRepo.Create(ctx, attempt); err != nil {
114			return nil, err
115		}
116	
117		// Save the selected question IDs
118		if err := uc.attemptRepo.SaveAttemptQuestions(ctx, attempt.ID, selected); err != nil {
119			return nil, err
120		}
121	
122		return attempt, nil
123	}
