129	func (uc *ExamUseCase) GetAttemptQuestions(ctx context.Context, attemptID uuid.UUID) ([]domain.Question, error) {
130		// Validate attempt exists
131		_, err := uc.attemptRepo.FindByID(ctx, attemptID)
132		if err != nil {
133			return nil, ErrAttemptNotFound
134		}
135	
136		// Get only the questions selected for this attempt
137		questionIDs, err := uc.attemptRepo.GetAttemptQuestionIDs(ctx, attemptID)
138		if err != nil {
139			return nil, err
140		}
141	
142		questions, err := uc.examRepo.GetQuestionsByIDs(ctx, questionIDs)
143		if err != nil {
144			return nil, err
145		}
146	
147		// Hide correct answers — client must never receive is_correct during active attempt
148		for i := range questions {
149			for j := range questions[i].Options {
150				questions[i].Options[j].IsCorrect = false
151			}
152		}
153	
154		return questions, nil
