157	func (uc *ExamUseCase) SubmitAnswer(ctx context.Context, attemptID uuid.UUID, userID uuid.UUID, req domain.SubmitAnswerRequest) (*domain.AttemptAnswer, error) {
158		attempt, err := uc.attemptRepo.FindByID(ctx, attemptID)
159		if err != nil {
160			return nil, ErrAttemptNotFound
161		}
162	
163		if attempt.UserID != userID {
164			return nil, errors.New("unauthorized")
165		}
166	
167		if attempt.Status != domain.AttemptStatusInProgress {
168			return nil, errors.New("attempt is not in progress")
169		}
170	
171		// Prevent duplicate answers: check if this question was already answered
172		hasAnswer, err := uc.attemptRepo.HasAnswer(ctx, attemptID, req.QuestionID)
173		if err != nil {
174			return nil, errors.New("failed to check existing answer")
175		}
176		if hasAnswer {
177			return nil, errors.New("question already answered")
178		}
179	
180		// Validate that the answered question belongs to this attempt's selected subset
181		isInAttempt, err := uc.attemptRepo.IsQuestionInAttempt(ctx, attemptID, req.QuestionID)
182		if err != nil {
183			return nil, errors.New("failed to validate question")
184		}
185		if !isInAttempt {
186			return nil, errors.New("question is not part of this attempt")
187		}
188	
189		question, err := uc.examRepo.FindQuestionByID(ctx, req.QuestionID)
190		if err != nil {
191			return nil, errors.New("question not found")
192		}
193	
194		isCorrect := checkAnswer(question, req.Answer)
195	
196		answer := &domain.AttemptAnswer{
197			ID:               uuid.New(),
198			AttemptID:        attemptID,
199			QuestionID:       req.QuestionID,
200			UserAnswer:       req.Answer,
201			IsCorrect:        &isCorrect,
202			TimeSpentSeconds: req.TimeSpentSeconds,
203			WasFlagged:       req.WasFlagged,
204			CreatedAt:        time.Now(),
205		}
206	
207		if err := uc.attemptRepo.SaveAnswer(ctx, answer); err != nil {
208			return nil, err
209		}
210	
211		// Update attempt progress
212		correctCount := attempt.QuestionsCorrect
213		if isCorrect {
214			correctCount++
215		}
216		if err := uc.attemptRepo.UpdateProgress(ctx, attemptID, attempt.QuestionsAnswered+1, correctCount); err != nil {
217			return nil, fmt.Errorf("update progress: %w", err)
218		}
219	
220		return answer, nil
221	}
