223	func (uc *ExamUseCase) CompleteAttempt(ctx context.Context, attemptID uuid.UUID, userID uuid.UUID) (*domain.Attempt, error) {
224		attempt, err := uc.attemptRepo.FindByID(ctx, attemptID)
225		if err != nil {
226			return nil, ErrAttemptNotFound
227		}
228	
229		if attempt.UserID != userID {
230			return nil, errors.New("unauthorized")
231		}
232	
233		if attempt.QuestionsTotal > 0 {
234			score := float64(attempt.QuestionsCorrect) / float64(attempt.QuestionsTotal) * 100
235			if err := uc.attemptRepo.Complete(ctx, attemptID, score, attempt.QuestionsCorrect, attempt.QuestionsAnswered); err != nil {
236				return nil, err
237			}
238		}
239	
240		return uc.attemptRepo.FindByID(ctx, attemptID)
241	}
