243	func (uc *ExamUseCase) GetAttemptWithDetails(ctx context.Context, attemptID uuid.UUID) (*domain.AttemptWithDetails, error) {
244		attempt, err := uc.attemptRepo.FindByID(ctx, attemptID)
245		if err != nil {
246			return nil, ErrAttemptNotFound
247		}
248	
249		// Get only the questions selected for this attempt
250		questionIDs, err := uc.attemptRepo.GetAttemptQuestionIDs(ctx, attemptID)
251		if err != nil {
252			return nil, err
253		}
254	
255		questions, err := uc.examRepo.GetQuestionsByIDs(ctx, questionIDs)
256		if err != nil {
257			return nil, err
258		}
259	
260		// Get user answers for this attempt
261		answers, err := uc.attemptRepo.GetAnswers(ctx, attemptID)
262		if err != nil {
263			return nil, err
264		}
265	
266		// Build answer lookup: questionID -> AttemptAnswer
267		answerMap := make(map[string]*domain.AttemptAnswer)
268		for i := range answers {
269			answerMap[answers[i].QuestionID.String()] = &answers[i]
270		}
271	
272		// Build the detailed questions list
273		detailed := make([]domain.AttemptQuestionWithAnswer, 0, len(questions))
274		for _, q := range questions {
275			qa := domain.AttemptQuestionWithAnswer{
276				ID:               q.ID,
277				Body:             q.Body,
278				Options:          q.Options,
279				QuestionType:     q.QuestionType,
280				Difficulty:       q.Difficulty,
281				Explanation:      q.Explanation,
282				ReferenceURLs:    q.ReferenceURLs,
283				BlueprintSection: q.BlueprintSection,
284			}
285			if ans, ok := answerMap[q.ID.String()]; ok {
286				qa.UserAnswer = ans.UserAnswer
287				qa.IsCorrect = ans.IsCorrect
288				qa.WasFlagged = ans.WasFlagged
289				qa.TimeSpentSeconds = ans.TimeSpentSeconds
290			}
291			detailed = append(detailed, qa)
292		}
293	
294		return &domain.AttemptWithDetails{
295			Attempt:   *attempt,
296			Questions: detailed,
297		}, nil
298	}
