304	func checkAnswer(question *domain.Question, answer string) bool {
305		switch question.QuestionType {
306		case domain.QuestionTypeFillBlank:
307			// For fill-blank, compare user text against the correct option's text (case-insensitive)
308			for _, opt := range question.Options {
309				if opt.IsCorrect {
310					return strings.EqualFold(strings.TrimSpace(answer), strings.TrimSpace(opt.Text))
311				}
312			}
313			return false
314	
315		case domain.QuestionTypeMultipleChoice:
316			// For multiple-choice, answer is comma-separated IDs like "a,b"
317			selectedIDs := strings.Split(answer, ",")
318			// Build map of correct option IDs
319			correctMap := make(map[string]bool)
320			for _, opt := range question.Options {
321				if opt.IsCorrect {
322					correctMap[opt.ID] = true
323				}
324			}
325			// Count correct selections
326			correctCount := 0
327			for _, id := range selectedIDs {
328				id = strings.TrimSpace(id)
329				if id == "" {
330					continue
331				}
332				if correctMap[id] {
333					correctCount++
334				}
335			}
336			// Must select ALL correct options and NO incorrect ones
337			return correctCount == len(correctMap) && correctCount == len(selectedIDs)
338	
339		default:
340			// Single-choice: match by option ID
341			for _, opt := range question.Options {
342				if opt.IsCorrect && opt.ID == answer {
343					return true
344				}
345			}
346			return false
347		}
348	}
