23	// defaultUpgrader is the package-level WebSocket upgrader config.
24	// It is replaced by SetAllowedOrigins() with origin-restricted validation.
25	var upgrader = defaultUpgrader()
26	
27	// defaultUpgrader returns a lenient upgrader for dev use.
28	func defaultUpgrader() websocket.Upgrader {
29		return websocket.Upgrader{
30			ReadBufferSize:  4096,
31			WriteBufferSize: 4096,
32			CheckOrigin: func(r *http.Request) bool {
33				return true // Allow all origins for dev; restrict in production
34			},
35		}
36	}
37	
38	// SetAllowedOrigins replaces the package-level upgrader with one that validates
39	// WebSocket upgrade requests against a list of allowed origins.
40	// Call this during server startup before any WebSocket connections are served.
41	func SetAllowedOrigins(origins []string) {
42		if len(origins) == 0 {
43			return
44		}
45		allowed := make(map[string]bool, len(origins))
46		for _, o := range origins {
47			allowed[strings.ToLower(o)] = true
48		}
49		upgrader = websocket.Upgrader{
50			ReadBufferSize:  4096,
51			WriteBufferSize: 4096,
52			CheckOrigin: func(r *http.Request) bool {
53				origin := strings.ToLower(r.Header.Get("Origin"))
54				// If no Origin header (same-origin request or non-browser client), allow
55				if origin == "" {
56					return true
57				}
58				return allowed[origin]
59			},
60		}
61	}
