93	// handleTerminal handles WebSocket ↔ SSH terminal connections for a lab device.
94	func (p *SSHProxy) handleTerminal(w http.ResponseWriter, r *http.Request) {
95		submissionID := chi.URLParam(r, "submissionID")
96		deviceName := chi.URLParam(r, "deviceName")
97	
98		conn, err := upgrader.Upgrade(w, r, nil)
99		if err != nil {
100			log.Printf("WebSocket upgrade failed: %v", err)
101			return
102		}
103		defer conn.Close()
104	
105		// Get lab devices from submission
106		subID, err := uuid.Parse(submissionID)
107		if err != nil {
108			log.Printf("Invalid submission ID: %s", submissionID)
109			writeWS(conn, "ERROR: Invalid submission ID")
110			return
111		}
112	
113		sub, err := p.labUC.GetSubmission(r.Context(), subID)
114		if err != nil || sub == nil {
115			log.Printf("Submission not found: %s", submissionID)
116			writeWS(conn, "ERROR: Lab session not found")
117			return
118		}
119	
120		// Find the target device in the submission
121		var targetDevice *domain.LabDevice
122		for _, d := range sub.Devices {
123			if d.Name == deviceName {
124				targetDevice = &d
125				break
126			}
127		}
128		if targetDevice == nil {
129			log.Printf("Device %s not found in submission %s", deviceName, submissionID)
130			writeWS(conn, fmt.Sprintf("ERROR: Device '%s' not found in lab", deviceName))
131			return
132		}
133	
134		// Strategy 1: Direct docker exec (fastest — no SSH overhead)
135		containerName := fmt.Sprintf("clab-%s-%s", sub.PodID, deviceName)
136		if p.tryDockerExec(conn, containerName) {
137			return
138		}
139	
140		// Strategy 2: SSH to device (fallback)
141		log.Printf("Docker exec failed for %s, trying SSH to %s", deviceName, targetDevice.MgmtIP)
142		p.trySSH(conn, targetDevice)
143	}
