145	// tryDockerExec attempts to connect via `docker exec -i`. Returns true if successful.
146	func (p *SSHProxy) tryDockerExec(ws *websocket.Conn, containerName string) bool {
147		cmd := exec.Command("docker", "exec", "-i", containerName, "cli")
148		stdin, err := cmd.StdinPipe()
149		if err != nil {
150			return false
151		}
152		stdout, err := cmd.StdoutPipe()
153		if err != nil {
154			return false
155		}
156		stderr, err := cmd.StderrPipe()
157		if err != nil {
158			return false
159		}
160	
161		if err := cmd.Start(); err != nil {
162			return false
163		}
164	
165		// WebSocket → docker stdin
166		go func() {
167			defer stdin.Close()
168			for {
169				_, msg, err := ws.ReadMessage()
170				if err != nil {
171					return
172				}
173				// Send the raw message; the user types commands with Enter
174				line := string(msg)
175				io.WriteString(stdin, line)
176				if !strings.HasSuffix(line, "\n") {
177					io.WriteString(stdin, "\n")
178				}
179			}
180		}()
181	
182		// docker stdout+stderr → WebSocket (merge both)
183		done := make(chan struct{})
184		go func() {
185			reader := io.MultiReader(stdout, stderr)
186			scanner := bufio.NewScanner(reader)
187			scanner.Buffer(make([]byte, 64*1024), 64*1024)
188			for scanner.Scan() {
189				data := scanner.Bytes()
190				ws.WriteMessage(websocket.BinaryMessage, append(data, '\n'))
191			}
192			close(done)
193		}()
194	
195		// Wait for command to finish (the connection is closed externally)
196		go func() {
197			cmd.Wait()
198			close(done)
199		}()
200	
201		// Don't block — this goroutine will clean up when done
202		return true
203	}
204	
205	// trySSH attempts to connect via SSH. Returns true if successful.
206	func (p *SSHProxy) trySSH(ws *websocket.Conn, device *domain.LabDevice) bool {
207		if device.MgmtIP == "" {
208			return false
209		}
210	
211		addr := fmt.Sprintf("%s:22", device.MgmtIP)
212		config := &ssh.ClientConfig{
213			User:            p.sshUser,
214			Auth:            []ssh.AuthMethod{ssh.Password(p.sshPass)},
215			HostKeyCallback: ssh.InsecureIgnoreHostKey(),
216			Timeout:         p.timeout,
217		}
218	
219		client, err := ssh.Dial("tcp", addr, config)
220		if err != nil {
221			return false
222		}
223		defer client.Close()
224	
225		session, err := client.NewSession()
226		if err != nil {
227			return false
228		}
229		defer session.Close()
230	
231		// Request PTY for JunOS CLI
232		if err := session.RequestPty("xterm-256color", 80, 24, ssh.TerminalModes{
233			ssh.ECHO:          1,
234			ssh.OPOST:         1,
235			ssh.ONLCR:         1,
236		}); err != nil {
237			return false
238		}
239	
240		stdin, err := session.StdinPipe()
241		if err != nil {
242			return false
243		}
244		stdout, err := session.StdoutPipe()
245		if err != nil {
246			return false
247		}
248	
249		if err := session.Shell(); err != nil {
250			return false
251		}
252	
253		// WebSocket → SSH stdin
254		go func() {
255			defer stdin.Close()
256			for {
257				_, msg, err := ws.ReadMessage()
258				if err != nil {
259					session.Close()
260					return
261				}
262				line := string(msg)
263				io.WriteString(stdin, line)
264				if !strings.HasSuffix(line, "\n") {
265					io.WriteString(stdin, "\n")
266				}
267			}
268		}()
269	
270		// SSH stdout → WebSocket
271		buf := make([]byte, 32*1024)
272		for {
273			n, err := stdout.Read(buf)
274			if err != nil {
275				break
276			}
277			ws.WriteMessage(websocket.BinaryMessage, buf[:n])
278		}
279	
280		return true
281	}
