283	// handleTopologyUpdates streams real-time topology status via WebSocket.
284	func (p *SSHProxy) handleTopologyUpdates(w http.ResponseWriter, r *http.Request) {
285		submissionID := chi.URLParam(r, "submissionID")
286	
287		conn, err := upgrader.Upgrade(w, r, nil)
288		if err != nil {
289			log.Printf("Topology WS upgrade failed: %v", err)
290			return
291		}
292		defer conn.Close()
293	
294		subID, err := uuid.Parse(submissionID)
295		if err != nil {
296			log.Printf("Invalid submission ID: %s", submissionID)
297			writeWS(conn, `{"error":"invalid submission ID"}`)
298			return
299		}
300	
301		sub, err := p.labUC.GetSubmission(r.Context(), subID)
302		if err != nil || sub == nil {
303			writeWS(conn, `{"error":"submission not found"}`)
304			return
305		}
306	
307		// Send initial snapshot
308		snapshot := map[string]interface{}{
309			"type":    "topology_snapshot",
310			"devices": sub.Devices,
311		}
312		data, _ := json.Marshal(snapshot)
313		conn.WriteMessage(websocket.TextMessage, data)
314	
315		// Keep-alive loop (ping/pong)
316		ticker := time.NewTicker(30 * time.Second)
317		defer ticker.Stop()
318	
319		done := make(chan struct{})
320		go func() {
321			defer close(done)
322			for {
323				if _, _, err := conn.ReadMessage(); err != nil {
324					return
325				}
326			}
327		}()
328	
329		for {
330			select {
331			case <-done:
332				return
333			case <-ticker.C:
334				if err := conn.WriteMessage(websocket.PingMessage, nil); err != nil {
335					return
336				}
337			}
338		}
339	}
