42	func Load() (*Config, error) {
43		jwtSecret := os.Getenv("JWT_SECRET")
44		if jwtSecret == "" {
45			return nil, errors.New("JWT_SECRET environment variable is required and cannot be empty")
46		}
47	
48		// Fail fast if running in production/staging with a known insecure secret
49		appEnv := os.Getenv("APP_ENV")
50		if appEnv != "development" && appEnv != "test" {
51			insecureSecrets := map[string]bool{
52				"netcert-dev-secret-change-in-production": true,
53				"changeme":                                true,
54				"secret":                                  true,
55				"test":                                    true,
56			}
57			if insecureSecrets[jwtSecret] {
58				return nil, errors.New("JWT_SECRET is set to a known insecure value; refusing to start in non-development environment")
59			}
60		}
61	
62		return &Config{
63			Server: ServerConfig{
64				Host:         getEnv("SERVER_HOST", "0.0.0.0"),
65				Port:         getEnv("SERVER_PORT", "8080"),
66				ReadTimeout:  15 * time.Second,
