32	func (m *JWTManager) GenerateAccessToken(userID uuid.UUID, email, role string) (string, error) {
33		claims := Claims{
34			UserID: userID,
35			Email:  email,
36			Role:   role,
37			RegisteredClaims: jwt.RegisteredClaims{
38				ExpiresAt: jwt.NewNumericDate(time.Now().Add(m.accessTokenTTL)),
39				IssuedAt:  jwt.NewNumericDate(time.Now()),
40				ID:        uuid.New().String(),
41			},
42		}
43	
44		token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
45		return token.SignedString(m.secret)
46	}
47	
48	func (m *JWTManager) GenerateRefreshToken(userID uuid.UUID) (string, error) {
49		claims := jwt.RegisteredClaims{
50			ExpiresAt: jwt.NewNumericDate(time.Now().Add(m.refreshTokenTTL)),
51			IssuedAt:  jwt.NewNumericDate(time.Now()),
52			ID:        uuid.New().String(),
53			Subject:   userID.String(),
54		}
55	
56		token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
57		return token.SignedString(m.secret)
58	}
