60	func (m *JWTManager) ValidateToken(tokenString string) (*Claims, error) {
61		token, err := jwt.ParseWithClaims(tokenString, &Claims{}, func(token *jwt.Token) (interface{}, error) {
62			if _, ok := token.Method.(*jwt.SigningMethodHMAC); !ok {
63				return nil, fmt.Errorf("unexpected signing method: %v", token.Header["alg"])
64			}
65			return m.secret, nil
66		})
67	
68		if err != nil {
69			return nil, err
70		}
71	
72		claims, ok := token.Claims.(*Claims)
73		if !ok || !token.Valid {
74			return nil, fmt.Errorf("invalid token")
75		}
76	
77		return claims, nil
78	}
