134	// deployTopology runs containerlab deploy in a goroutine.
135	func (uc *LabUseCase) deployTopology(submissionID uuid.UUID, lab *domain.Lab, podID string) {
136		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
137		defer cancel()
138	
139		clabDir := fmt.Sprintf("%s/%s", uc.clabDir, podID)
140		clabFile := fmt.Sprintf("%s/clab.yml", clabDir)
141	
142		// Create directory and write topology YAML
143		mkdirCmd := exec.CommandContext(ctx, "mkdir", "-p", clabDir)
144		if err := mkdirCmd.Run(); err != nil {
145			log.Printf("Lab %s: mkdir failed: %v", submissionID, err)
146			uc.labRepo.UpdateSubmissionStatus(context.Background(), submissionID, domain.LabStatusFailed, nil, 0)
147			return
148		}
149	
150		// Write the topology file
151		writeFile := fmt.Sprintf("cat > %s << 'CLABEOF'\n%s\nCLABEOF", clabFile, lab.TopologyYAML)
152		writeCmd := exec.CommandContext(ctx, "sh", "-c", writeFile)
153		if err := writeCmd.Run(); err != nil {
154			log.Printf("Lab %s: write clab.yml failed: %v", submissionID, err)
155			uc.labRepo.UpdateSubmissionStatus(context.Background(), submissionID, domain.LabStatusFailed, nil, 0)
156			return
157		}
158	
159		// Run containerlab deploy
160		deployCmd := exec.CommandContext(ctx, uc.clabBinPath, "deploy", "-t", clabFile)
161		output, err := deployCmd.CombinedOutput()
162		if err != nil {
163			log.Printf("Lab %s: containerlab deploy failed: %v\nOutput: %s", submissionID, err, string(output))
164			uc.labRepo.UpdateSubmissionStatus(context.Background(), submissionID, domain.LabStatusFailed, nil, 0)
165			return
166		}
167	
168		log.Printf("Lab %s: deployed successfully\n%s", submissionID, string(output))
169	
170		// Parse device info from containerlab inspect
171		devices := uc.parseDevicesFromDeploy(ctx, podID)
172	
173		// Update submission with device info
174		uc.labRepo.UpdateSubmissionStatus(context.Background(), submissionID, domain.LabStatusRunning, devices, 0)
175	}
