177	// parseDevicesFromDeploy runs `containerlab inspect` to get device details.
178	func (uc *LabUseCase) parseDevicesFromDeploy(ctx context.Context, podID string) []domain.LabDevice {
179		// Use containerlab inspect to get device information
180		inspectCmd := exec.CommandContext(ctx, uc.clabBinPath, "inspect", "-n", podID, "--format", "json")
181		output, err := inspectCmd.CombinedOutput()
182		if err != nil {
183			log.Printf("Failed to inspect lab %s: %v\nOutput: %s", podID, err, string(output))
184			// Fallback: try docker ps to get running containers
185			return uc.fallbackDevices(podID)
186		}
187	
188		// Parse JSON output from containerlab inspect
189		return uc.parseCLabJSON(string(output), podID)
190	}
