237	func (uc *LabUseCase) fallbackDevices(podID string) []domain.LabDevice {
238		// Use docker ps to find containers belonging to this lab
239		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
240		defer cancel()
241	
242		cmd := exec.CommandContext(ctx, "docker", "ps", "--filter", fmt.Sprintf("name=clab-%s-", podID), "--format", "{{.Names}}")
243		output, err := cmd.CombinedOutput()
244		if err != nil {
245			log.Printf("Fallback devices failed for %s: %v", podID, err)
246			return nil
247		}
248	
249		var devices []domain.LabDevice
250		for _, name := range strings.Split(strings.TrimSpace(string(output)), "\n") {
251			if name == "" {
252				continue
253			}
254			parts := strings.Split(name, "-")
255			deviceName := parts[len(parts)-1]
256			devices = append(devices, domain.LabDevice{
257				Name:   deviceName,
258				Kind:   "juniper_crpd",
259				Status: domain.DeviceStatusRunning,
260			})
261		}
262		return devices
263	}
