437	// runGradeScript reads a grade.py script and executes it inside the DinD container
438	// via the host Docker socket. The grade.py script connects to lab devices via SSH
439	// using their management IPs (only reachable from inside the DinD container).
440	func (uc *LabUseCase) runGradeScript(ctx context.Context, scriptPath string, extraArgs []string) ([]byte, error) {
441		// Read the Python script content from disk
442		scriptBytes, err := os.ReadFile(scriptPath)
443		if err != nil {
444			return nil, fmt.Errorf("read grade script %s: %w", scriptPath, err)
445		}
446	
447		// Build docker exec command to run the script inside DinD
448		// Use the host Docker socket (not DOCKER_HOST pointing to DinD) so we can
449		// exec into the clab-dind container itself (not from inside DinD's Docker)
450		// The -H flag overrides DOCKER_HOST for this specific command.
451		args := []string{
452			"-H", fmt.Sprintf("unix://%s", uc.hostDockerSocket),
453			"exec", "-i", uc.dindContainer,
454			"python3", "-",
455			"--output", "json",
456		}
457		args = append(args, extraArgs...)
458	
459		cmd := exec.CommandContext(ctx, "docker", args...)
460		cmd.Stdin = bytes.NewReader(scriptBytes)
461	
462		output, err := cmd.CombinedOutput()
463		if err != nil {
464			// If the command failed, include the output in the error for debugging
465			return nil, fmt.Errorf("docker exec failed: %w\nOutput: %s", err, string(output))
466		}
467	
468		// Strip any non-JSON prefix (e.g., warnings printed to stdout before JSON)
469		outStr := strings.TrimSpace(string(output))
470		jsonStart := strings.Index(outStr, "{")
471		if jsonStart > 0 {
472			outStr = outStr[jsonStart:]
473		}
474	
475		return []byte(outStr), nil
476	}
