192	func (uc *LabUseCase) parseCLabJSON(output, podID string) []domain.LabDevice {
193		var devices []domain.LabDevice
194	
195		// Simple line-based parser for containerlab inspect JSON
196		// Format: {"containers":{"clab-{pod}-{name}":{"name":"{name}","kind":"{kind}","mgmt_ip":"...",...}}}
197		lines := strings.Split(output, "\n")
198		currentName := ""
199		for _, line := range lines {
200			trimmed := strings.TrimSpace(line)
201			if strings.Contains(trimmed, fmt.Sprintf(`"clab-%s-`, podID)) {
202				// Extract device name from container name: "clab-{pod}-{name}"
203				parts := strings.Split(trimmed, `"`)
204				for _, p := range parts {
205					if strings.Contains(p, fmt.Sprintf("clab-%s-", podID)) {
206						nameParts := strings.Split(p, "-")
207						if len(nameParts) > 3 {
208							currentName = strings.Join(nameParts[3:], "-")
209						}
210					}
211				}
212			}
213			if currentName != "" && strings.Contains(trimmed, `"mgmt_ip"`) {
214				parts := strings.Split(trimmed, `"`)
215				for i, p := range parts {
216					if p == "mgmt_ip" && i+2 < len(parts) {
217						ip := parts[i+2]
218						devices = append(devices, domain.LabDevice{
219							Name:   currentName,
220							Kind:   "juniper_crpd",
221							MgmtIP: ip,
222							Status: domain.DeviceStatusRunning,
223						})
224						currentName = ""
225						break
226					}
227				}
228			}
229		}
230	
231		if len(devices) == 0 {
232			return uc.fallbackDevices(podID)
233		}
234		return devices
235	}
