331	// SubmitModule grades a specific module of the lab by running the lab's
332	// grade.py script via docker exec inside the Containerlab DinD container.
333	func (uc *LabUseCase) SubmitModule(ctx context.Context, userID uuid.UUID, req *domain.LabSubmitModuleRequest) (*domain.LabScore, error) {
334		sub, err := uc.labRepo.GetSubmission(ctx, req.SubmissionID)
335		if err != nil {
336			return nil, fmt.Errorf("get submission: %w", err)
337		}
338		if sub == nil || sub.UserID != userID {
339			return nil, fmt.Errorf("submission not found or access denied")
340		}
341	
342		// Load the lab template to get grading script path
343		lab, err := uc.labRepo.GetByID(ctx, sub.LabID)
344		if err != nil {
345			return nil, fmt.Errorf("get lab: %w", err)
346		}
347		if lab == nil {
348			return nil, fmt.Errorf("lab not found")
349		}
350	
351		// Build device IP arguments from submission's devices
352		// Map device names to their management IPs
353		// grade.py expects flags like: --r1-ip <ip> --r2-ip <ip> --r3-ip <ip>
354		var deviceArgs []string
355		for _, dev := range sub.Devices {
356			if dev.MgmtIP != "" {
357				deviceArgs = append(deviceArgs, fmt.Sprintf("--%s-ip", dev.Name), dev.MgmtIP)
358			}
359		}
360	
361		// Determine the grading script path on disk
362		if lab.GradingScript == "" {
363			return nil, fmt.Errorf("lab has no grading script configured")
364		}
365		if lab.LabDirectory == "" {
366			return nil, fmt.Errorf("lab has no lab_directory configured")
367		}
368	
369		// Path construction:
370		//   lab_directory = "backend/labs/micro-labs/01-junos-cli-basics"
371		//   labsBaseDir   = "/app/labs" (mounted from ../backend/labs)
372		//   GradingScript = "01-junos-cli-basics/grade.py"
373		//   → /app/labs/micro-labs/01-junos-cli-basics/grade.py
374		//
375		// Strip the "backend/labs/" prefix from lab_directory to get the
376		// path relative to labsBaseDir, then append the grade.py filename.
377		relDir := strings.TrimPrefix(lab.LabDirectory, "backend/labs/")
378		gradeScriptPath := filepath.Join(uc.labsBaseDir, relDir, filepath.Base(lab.GradingScript))
379	
380		// Run the grading script inside the DinD container via the host Docker socket
381		var gradeOutput []byte
382		gradeOutput, err = uc.runGradeScript(ctx, gradeScriptPath, deviceArgs)
383		if err != nil {
384			log.Printf("SubmitModule: grade.py execution failed: %v", err)
385			// Fallback: return a zero score with error info
386			return uc.saveZeroScore(ctx, sub, req, fmt.Sprintf("grading error: %v", err))
387		}
388	
389		// Parse the JSON output from grade.py
390		var pyResult domain.PythonGradeOutput
391		if err := json.Unmarshal(gradeOutput, &pyResult); err != nil {
392			log.Printf("SubmitModule: failed to parse grade.py JSON: %v\nRaw: %s", err, string(gradeOutput))
393			return uc.saveZeroScore(ctx, sub, req, fmt.Sprintf("parse error: %v", err))
394		}
395	
396		// Convert Python grading tasks to ScoringCheck array
397		scoringChecks := make([]domain.ScoringCheck, 0, len(pyResult.Tasks))
398		for taskID, task := range pyResult.Tasks {
399			scoringChecks = append(scoringChecks, domain.ScoringCheck{
400				Command:       taskID,
401				ExpectedMatch: "",
402				ActualOutput:  task.Detail,
403				Passed:        task.Passed,
404				PointsAwarded: task.Score,
405				MaxPoints:     task.MaxScore,
406			})
407		}
408	
409		// Build LabScore from grade result
410		score := &domain.LabScore{
411			ID:            uuid.New(),
412			SubmissionID:  req.SubmissionID,
413			ModuleNumber:  req.ModuleNumber,
414			ModuleTitle:   pyResult.Title,
415			TaskScore:     pyResult.TotalScore,
416			MaxScore:      pyResult.MaxScore,
417			ScoringOutput: scoringChecks,
418			IsAutoGraded:  true,
419			CreatedAt:     time.Now().UTC(),
420		}
421	
422		if err := uc.labRepo.SaveLabScore(ctx, score); err != nil {
423			return nil, fmt.Errorf("save score: %w", err)
424		}
425	
426		// Update submission current_score
427		scores, _ := uc.labRepo.GetLabScores(ctx, req.SubmissionID)
428		total := 0
429		for _, s := range scores {
430			total += s.TaskScore
431		}
432		uc.labRepo.UpdateSubmissionStatus(ctx, req.SubmissionID, sub.Status, sub.Devices, total)
433	
434		return score, nil
435	}
